<script setup>
import { computed, inject, onMounted, ref } from "vue"; import { RouterLink } from "vue-router"; import PageHeader from "../components/PageHeader.vue"; import EmptyState from "../components/EmptyState.vue"; import StatusBadge from "../components/StatusBadge.vue";
const props = defineProps({ elementId: String }); const services = inject("services"); const element = ref(); const evaluation = ref(); const result = computed(() => evaluation.value?.result ?? []); const failed = computed(() => result.value.filter(item => ["nao_conforme", "erro", "invalido"].includes(item.status)).length); const pending = computed(() => result.value.filter(item => ["nao_avaliado", "manual", "atencao"].includes(item.status)).length); const overall = computed(() => failed.value ? "nao_conforme" : pending.value ? "nao_avaliado" : "conforme");
onMounted(async () => { element.value = await services.repositories.elementRepository.get(props.elementId); if (element.value) evaluation.value = (await services.evaluationService.listEvaluations(element.value.id))[0]; });
</script>
<template><template v-if="element && evaluation"><RouterLink class="back-link" :to="`/elements/${element.id}`">‹ {{ element.name }}</RouterLink><PageHeader eyebrow="Resultado" title="Avaliação" :description="`Realizada em ${new Intl.DateTimeFormat('pt-BR', { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(evaluation.evaluatedAt))}`" /><section class="result-summary" :class="`result-summary--${overall}`"><StatusBadge :status="overall" /><h2>{{ overall === 'conforme' ? 'Elemento conforme' : overall === 'nao_conforme' ? 'Há itens não conformes' : 'Avaliação pendente' }}</h2><p>{{ result.length - failed - pending }} regra(s) atendida(s), {{ failed }} não conforme(s) e {{ pending }} para verificar.</p></section><section class="results"><h2>Regras avaliadas</h2><article v-for="item in result" :key="item.id" class="result-row" :class="`result-row--${item.status}`"><div><StatusBadge :status="item.status" /><h3>{{ item.nome ?? item.id }}</h3><p v-if="item.mensagem">{{ item.mensagem }}</p><p v-if="item.valorInformado !== undefined" class="result-values">Informado: <strong>{{ item.valorInformado }}</strong>{{ item.unidade ? ` ${item.unidade}` : '' }}{{ item.valorEsperado !== undefined ? ` · Esperado: ${item.valorEsperado}` : '' }}</p><small>{{ item.referencia }}</small></div></article></section></template><template v-else-if="element"><RouterLink class="back-link" :to="`/elements/${element.id}`">‹ Elemento</RouterLink><EmptyState title="Ainda não há avaliação" text="Preencha os dados do elemento para executar as regras."><RouterLink class="button" :to="`/elements/${element.id}`">Avaliar elemento</RouterLink></EmptyState></template><EmptyState v-else title="Avaliação não encontrada" text="O elemento pode ter sido removido."><RouterLink class="button" to="/projects">Projetos</RouterLink></EmptyState></template>
